      "model_id": "seasonal_naive"
    },
    {
      "claim": {
        "evidence_ids": ["catalog.hw_add"],
        "text": "Holt-Winters additive model with damped trend and additive seasonality may capture additive seasonal shifts and trend decay."
      },
      "model_id": "hw_add"
    },
    {
      "claim": {
        "evidence_ids": ["catalog.hw_mul"],
        "text": "Holt-Winters multiplicative seasonality may better handle proportional seasonal variation as levels change over time."
      },
      "model_id": "hw_mul"
    }
  ],
  "limitation": {
    "evidence_ids": ["limitations.scope", "limitations.uncertainty", "limitations.vintage", "limitations.workflow"],
    "text": "Performance is based on one series, point forecasts only, no real-time vintage, and catalog selection is fixed outside modeler control."
  }
}

